def fmt_native(cid, t):
    n = t['native']
    if not t['nativeLegs']: return 'No native legs.'
    s = '%d native legs, %d of them the only PoolManager transaction of their block; in all %d the PoolManager balance difference that block production wrote equals the payment' % (t['nativeLegs'], n.get('alone', 0), n.get('aloneBalanceAgrees', 0))
    if n.get('aloneBalanceDisagrees'): s += ' (%d disagree)' % n['aloneBalanceDisagrees']
    via = [('call tracer', n.get('via trace', 0)), ('balance difference, no tracer answered', n.get('via balance', 0)), ('system emitter logs', n.get('via systemLogs', 0))]
    s += '. Payments were read from: ' + ', '.join('%s %d' % (k, v) for k, v in via if v)
    if n.get('systemLogsAgree'): s += '; the system emitter logs equal the owed amount in all %d' % n['systemLogsAgree']
    return s + '.'


